package dev.utherhel.effectification.mixin.client;

import dev.utherhel.effectification.selftest.ClientSelfTest;
import dev.kikugie.fletching_table.mixin.MixinEnvironment;
import net.minecraft.client.Minecraft;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;

/** Drives the dev self-test from the client tick; inert unless -Deffectification.selftest is set. Generated by dev/modtest/sync.py. */
@MixinEnvironment(type = MixinEnvironment.Env.CLIENT)
@Mixin(Minecraft.class)
public abstract class SelfTestClientMixin {
    @Inject(method = "tick", at = @At("TAIL"))
    private void effectification$modtestTick(CallbackInfo ci) {
        if (ClientSelfTest.active()) ClientSelfTest.onClientTick((Minecraft) (Object) this);
    }
}
